#include <stdio.h>
int main() {
    int data[] = {15, 12, 26, 23, 31, 36};
    int temp = 0;
    int cnt = sizeof(data)/sizeof(int);
    for(int i=0; i<cnt; i++) {
        for(int j=i; j<5-i; j++) {
            if(data[j] > data[j+1]) {
                temp = data[j];
                data[j] = data[j+1];
                data[j+1] = temp;
            }
        }
    }
    for(int i=1; i<cnt-1; i++) {
        printf("%d ", data[i]);
    }
}

